    fun build(width: Int, quality: Int): ByteArray {
        require(width == 320 || width == 400) { "unsupported width $width" }
        require(quality in 1..95) { "unsupported quality $quality" }
        val header = TEMPLATE.copyOf()
        val scale = if (quality < 50) 5000 / quality else 200 - 2 * quality
        for (table in 0..1) {
            val offset = if (table == 0) 25 else 94
            for (i in 0 until 64) {
                var value = (TEMPLATE[offset + i].toInt() and 0xFF) * scale
                value = (value + 50) / 100
                if (value < 1) value = 1
                if (value > 255) value = 255
                header[offset + i] = value.toByte()
            }
        }
        // DRI: restart interval = width / 16 MCUs.
        header[162] = 0
        header[163] = (width / 16).toByte()
        // SOF0 width (big-endian) at 171..172; height stays 240.
        header[171] = (width shr 8).toByte()
        header[172] = (width and 0xFF).toByte()
        return header
    }

    /** Expands an 8-byte compact frame into a decodable full JPEG. */
    fun expand(compact: ByteArray): ByteArray {
        val width = compact[6].toInt() and 0xFF or ((compact[7].toInt() and 0xFF) shl 8)
        val quality = compact[5].toInt() and 0xFF
        val header = build(width, quality)
        val scan = compact.size - 8
        val out = ByteArray(FULL_SIZE + scan)
        System.arraycopy(header, 0, out, 0, FULL_SIZE)
        System.arraycopy(compact, 8, out, FULL_SIZE, scan)
        return out
    }
